  const { user } = useAuthStore();

  // Estados para controlar carregamento e mensagens
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true); // Para carregar dados ao abrir a página
  const [message, setMessage] = useState({ type: '', text: '' });

  // Estado do formulário (nomes alinhados com a interface, mapearemos no envio)
  const [formData, setFormData] = useState({
    companyName: '',
    cnpj: '',
    state: '',
    softwareConsultoria: false,
    softwareContabil: false,
    softwareFiscal: false,
    clientesHoje: 0,
    clientesAno: 0,
    funcionariosHoje: 0,
    funcionariosAno: 0,
    visaoEmpresa: '',
    maiorDesafio: '',
    compromisso: '',
  });

  const estados = [
    'AC', 'AL', 'AP', 'AM', 'BA', 'CE', 'DF', 'ES', 'GO', 'MA',
    'MT', 'MS', 'MG', 'PA', 'PB', 'PR', 'PE', 'PI', 'RJ', 'RN',
    'RS', 'RO', 'RR', 'SC', 'SP', 'SE', 'TO'
  ];

  /**
   * CARREGAR DADOS: Busca os dados salvos no backend quando a página abre
   */
  useEffect(() => {
    async function loadCompanyData() {
      try {
        const response = await api.get('/company');
        const data = response.data.data;

        if (data) {
          // Mapeia os dados do backend (nome em português) para o estado do frontend (nome em inglês)
          setFormData({
            companyName: data.razaoSocial || '',
            cnpj: data.cnpj || '',
            state: data.estado || '',
            softwareConsultoria: data.softwareConsultoria || false,
            softwareContabil: data.softwareContabil || false,
            softwareFiscal: data.softwareFiscal || false,
            clientesHoje: data.clientesHoje || 0,
            clientesAno: data.clientesAno || 0,
            funcionariosHoje: data.funcionariosHoje || 0,
            funcionariosAno: data.funcionariosAno || 0,
            visaoEmpresa: data.visaoEmpresa || '',
            maiorDesafio: data.maiorDesafio || '',
            compromisso: data.compromisso || '',
          });
        }
      } catch (error) {
        console.error('Erro ao carregar dados da empresa:', error);
      } finally {
        setFetching(false); // Terminou de carregar
      }
    }

    loadCompanyData();
  }, []);

  /**
   * SALVAR DADOS: Envia o formulário para o backend
   */
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ type: '', text: '' });

    try {
      // Mapeia o estado do frontend para o formato esperado pelo DTO do backend
      const payload = {
        razaoSocial: formData.companyName,
        cnpj: formData.cnpj,
        estado: formData.state,
        softwareConsultoria: formData.softwareConsultoria,
        softwareContabil: formData.softwareContabil,
        softwareFiscal: formData.softwareFiscal,
