        visaoEmpresa: formData.visaoEmpresa,
        maiorDesafio: formData.maiorDesafio,
        compromisso: formData.compromisso,
      };

      // Chama a API real (POST /company)
      // O token JWT é injetado automaticamente pelo interceptor do axios (src/lib/axios.ts)
      await api.post('/company', payload);

      setMessage({
        type: 'success',
        text: 'Dados da empresa salvos com sucesso no banco de dados!'
      });
    } catch (error: any) {
      console.error('Erro ao salvar:', error);
      setMessage({
        type: 'error',
        text: error.response?.data?.message || 'Erro ao salvar dados. Tente novamente.'
      });
    } finally {
      setLoading(false);
    }
