### 📄 **ARQUIVO 4: `frontend/src/app/dashboard/pessoas/page.tsx`**

**Problema:** Estava correto, mas vou adicionar tratamento de erro 401 específico.
**Solução:** Versão com melhor feedback visual.

```typescript
'use client';

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import {
  Users,
  UserPlus,
  UserMinus,
  TrendingDown,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
} from 'lucide-react';

/**
 * Tipos TypeScript para os dados de colaboradores
 * 
 * POR QUE USAR INTERFACES?
 * - O TypeScript valida os dados em tempo de compilação
 * - Autocomplete no VS Code
 * - Evita erros de digitação em nomes de campos
 */
interface Employee {
  id: string;
  name: string;
  email: string;
  phone: string;
  position: string;
  department: string;
  admissionDate: string;
  dismissalDate: string | null;
  salary: number;
  status: string;
}

interface Metrics {
  totalActive: number;
  totalEmployees: number;
  admissionsThisMonth: number;
  dismissalsThisMonth: number;
  turnoverRate: number;
}

export default function PessoasPage() {
  const { user } = useAuthStore();

  // Estados principais de dados
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Estados de UI
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Estado do formulário
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    position: '',
    department: '',
    admissionDate: '',
    dismissalDate: '',
    salary: '',
  });

  /**
   * CARREGA OS DADOS AO ABRIR A PÁGINA
   * 
   * POR QUE USAR Promise.all?
   * - Faz as duas requisições AO MESMO TEMPO (paralelo)
   * - Mais rápido que fazer uma depois da outra (sequencial)
   * - Se uma falhar, a outra ainda pode funcionar
   */
  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);

      const [empRes, metRes] = await Promise.all([
        api.get('/employees'),
        api.get('/employees/metrics'),
      ]);

      setEmployees(empRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      console.error('Erro ao carregar dados:', err);

      // Se foi erro 401, o interceptor do axios já fez logout
      // Não precisamos mostrar erro aqui
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados. Tente recarregar a página.');
      }
    } finally {
      setLoading(false);
    }
  }

  /**
   * FILTRA COLABORADORES PELA BUSCA
   * 
   * Executa em tempo real conforme o usuário digita
   * Busca em: nome, cargo e departamento
   */
  const filteredEmployees = employees.filter(
    (emp) =>
      emp.name.toLowerCase().includes(search.toLowerCase()) ||
      emp.position.toLowerCase().includes(search.toLowerCase()) ||
      emp.department?.toLowerCase().includes(search.toLowerCase()),
  );

  /**
   * ABRE O FORMULÁRIO (criar ou editar)
   * 
   * Se passar um employee → modo edição (preenche os campos)
   * Se não passar → modo criação (campos vazios)
   */
  function openForm(employee?: Employee) {
    if (employee) {
      setEditingId(employee.id);
      setForm({
        name: employee.name,
        email: employee.email || '',
        phone: employee.phone || '',
        position: employee.position,
        department: employee.department || '',
        admissionDate: employee.admissionDate.split('T')[0],
        dismissalDate: employee.dismissalDate?.split('T')[0] || '',
        salary: employee.salary?.toString() || '',
      });
    } else {
      setEditingId(null);
      setForm({
        name: '',
        email: '',
        phone: '',
        position: '',
        department: '',
        admissionDate: '',
        dismissalDate: '',
        salary: '',
      });
    }
    setShowForm(true);
  }

  /**
   * SALVA O COLABORADOR (criar ou atualizar)
   * 
   * Se editingId existe → PUT (atualizar)
   * Se não existe → POST (criar novo)
   */
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);

    try {
      const payload = {
        ...form,
        salary: form.salary ? parseFloat(form.salary) : undefined,
        admissionDate: form.admissionDate,
        dismissalDate: form.dismissalDate || undefined,
      };

      if (editingId) {
        await api.put(`/employees/${editingId}`, payload);
      } else {
        await api.post('/employees', payload);
      }

      setShowForm(false);
      await loadData(); // Recarrega a tabela
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      alert('Erro ao salvar colaborador. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  /**
   * REMOVE UM COLABORADOR
   * 
   * Pede confirmação antes de deletar (evita cliques acidentais)
   */
  async function handleDelete(id: string) {
    if (!confirm('Tem certeza que deseja remover este colaborador?')) return;

    try {
      await api.delete(`/employees/${id}`);
      await loadData();
    } catch (err: any) {
      console.error('Erro ao remover:', err);
      alert('Erro ao remover colaborador.');
    }
  }

  // TELA DE CARREGAMENTO
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // TELA DE ERRO
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button
            onClick={loadData}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl">
      {/* Cabeçalho */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">
            Gestão de Pessoas
          </h1>
          <p className="text-slate-600">
            Acompanhe o quadro de colaboradores e métricas de turnover
          </p>
        </div>
        <button
          onClick={() => openForm()}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors"
        >
          <Plus className="h-5 w-5" />
          Novo Colaborador
        </button>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-8">
          <MetricCard icon={Users} label="Total Ativos" value={metrics.totalActive} color="blue" />
          <MetricCard icon={UserPlus} label="Admissões (mês)" value={metrics.admissionsThisMonth} color="green" />
          <MetricCard icon={UserMinus} label="Demissões (mês)" value={metrics.dismissalsThisMonth} color="red" />
          <MetricCard icon={TrendingDown} label="Turnover" value={`${metrics.turnoverRate}%`} color="orange" />
          <MetricCard icon={Users} label="Total Geral" value={metrics.totalEmployees} color="purple" />
        </div>
      )}

      {/* Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nome, cargo ou departamento..."
            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Tabela */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredEmployees.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <Users className="h-12 w-12 mx-auto mb-4 text-slate-300" />
            <p className="text-lg font-medium">Nenhum colaborador cadastrado</p>
            <p className="text-sm mt-1">Clique em "Novo Colaborador" para começar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Nome</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Cargo</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Departamento</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Admissão</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Status</th>
                  <th className="text-right px-6 py-3 text-xs font-medium text-slate-500 uppercase">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {filteredEmployees.map((emp) => (
                  <tr key={emp.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-900">{emp.name}</div>
                      {emp.email && <div className="text-sm text-slate-500">{emp.email}</div>}
                    </td>
                    <td className="px-6 py-4 text-slate-700">{emp.position}</td>
                    <td className="px-6 py-4 text-slate-700">{emp.department || '-'}</td>
                    <td className="px-6 py-4 text-slate-700">
                      {new Date(emp.admissionDate).toLocaleDateString('pt-BR')}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
