/**
 * COMPONENTE AUXILIAR: Card de Métrica
 * 
 * Reutilizável para exibir qualquer métrica com ícone colorido
 */
function MetricCard({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: any;
  label: string;
  value: string | number;
  color: string;
}) {
  const colorClasses: Record<string, string> = {
    blue: 'bg-blue-100 text-blue-600',
    green: 'bg-green-100 text-green-600',
