### **📄 2. `frontend/src/app/dashboard/layout.tsx`**

```typescript
'use client';

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuthStore } from '@/store/authStore';
import Sidebar from '@/components/Sidebar';
import { Loader2 } from 'lucide-react';

/**
 * Layout do Dashboard
 * 
 * Este componente envolve todas as páginas do dashboard e:
 * 1. Verifica se o usuário está autenticado
 * 2. Mostra loading enquanto carrega os dados do localStorage
 * 3. Redireciona para login se não estiver autenticado
 * 4. Renderiza o Sidebar e o conteúdo da página
 */
export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const { user, token, isLoading } = useAuthStore();

  /**
   * Efeito de verificação de autenticação
   * 
   * IMPORTANTE: Só executa a verificação APÓS o carregamento do localStorage estar completo.
   * Isso evita redirecionamentos prematuros durante a navegação entre páginas.
   */
  useEffect(() => {
    // Se ainda estiver carregando, não faz nada
    if (isLoading) {
      return;
    }

    // Se não estiver carregando e não tiver usuário ou token, redireciona
    if (!user || !token) {
      router.push('/login');
    }
  }, [user, token, isLoading, router]);

  /**
   * Tela de Loading
   * 
   * Mostra um spinner enquanto os dados do localStorage estão sendo carregados.
   * Isso é crucial para evitar flashes de conteúdo e redirecionamentos errados.
   */
  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-3 text-slate-600">Carregando...</span>
      </div>
    );
  }

  /**
   * Proteção de Rota
   * 
   * Se não tiver usuário ou token após o carregamento, não renderiza nada.
   * O useEffect acima já cuidou do redirecionamento.
   */
  if (!user || !token) {
    return null;
  }

  /**
   * Renderização Principal
   * 
   * Mostra o layout completo com Sidebar e conteúdo da página.
   */
  return (
    <div className="flex min-h-screen bg-slate-50">
      <Sidebar />
      <main className="flex-1 p-8 overflow-auto">
        {children}
      </main>
    </div>
  );
}
