### ** 3. `frontend/src/lib/axios.ts`**

```typescript
import axios from 'axios';
import { useAuthStore } from '@/store/authStore';

/**
 * Instância do Axios configurada para a API
 * 
 * Cria uma instância personalizada do axios com:
 * - URL base da API (vinda do .env.local ou padrão)
 * - Headers padrão para JSON
 * - Interceptors para autenticação automática
 */
const api = axios.create({
  baseURL: process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3001',
  headers: {
    'Content-Type': 'application/json',
  },
});

/**
 * Interceptor de Requisição
 * 
 * Adiciona automaticamente o token JWT em todas as requisições.
 * Isso elimina a necessidade de passar o token manualmente em cada chamada.
 * 
 * Fluxo:
 * 1. Antes de cada requisição, pega o token do Zustand store
 * 2. Se existir token, adiciona no header Authorization
 * 3. Continua com a requisição normalmente
 */
api.interceptors.request.use(
  (config) => {
    const { token } = useAuthStore.getState();

    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }

    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

/**
 * Interceptor de Resposta
 * 
 * Lida com erros de autenticação automaticamente.
 * Se receber 401 (Unauthorized), faz logout e redireciona para login.
 * 
 * Fluxo:
 * 1. Se a requisição foi bem-sucedida, retorna a resposta normalmente
 * 2. Se recebeu erro 401, limpa o store e redireciona para login
 * 3. Outros erros são propagados para tratamento na camada superior
 */
api.interceptors.response.use(
  (response) => response,
  (error) => {
    // Verifica se é erro de autenticação (401 Unauthorized)
    if (error.response?.status === 401) {
      // Faz logout limpando o store
      useAuthStore.getState().logout();

      // Redireciona para a página de login
      window.location.href = '/login';
    }

    return Promise.reject(error);
  }
);

export default api;
```

