 */
interface Metrics {
  totalActive: number;
  totalEmployees: number;
  admissionsThisMonth: number;
  dismissalsThisMonth: number;
  turnoverRate: number;
}

/**
 * Página de Gestão de Pessoas
 * 
 * Componente principal que exibe:
 * - Dashboard com métricas de turnover
 * - Lista de colaboradores com busca
 * - Formulário modal para criar/editar colaboradores
 * - Funcionalidades de exclusão
 */
