  /**
   * Função para carregar dados do backend
   * 
   * Faz duas requisições em paralelo para otimizar performance:
   * 1. GET /employees - Lista de colaboradores
   * 2. GET /employees/metrics - Métricas de turnover
   */
  async function loadData() {
    try {
      setLoading(true);

      // Faz as duas requisições simultaneamente
      const [empRes, metRes] = await Promise.all([
        api.get('/employees'),
        api.get('/employees/metrics'),
      ]);

      // Atualiza os estados com os dados recebidos
      setEmployees(empRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (error) {
      console.error('Erro ao carregar dados:', error);
