```typescript
'use client';

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import {
  Briefcase,
  UserPlus,
  TrendingUp,
  DollarSign,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
} from 'lucide-react';

// --- TIPOS (Para o TypeScript nos ajudar) ---
interface Client {
  id: string;
  companyName: string;
  cnpj: string;
  serviceType: string;
  monthlyFee: number;
  status: string;
  startDate: string;
  endDate: string | null;
  contactName: string;
  contactEmail: string;
  contactPhone: string;
  observations: string;
}

interface Metrics {
  totalActive: number;
  totalClients: number;
  monthlyRevenue: number;
  newClientsThisMonth: number;
  averageTicket: number;
}

export default function ClientesPage() {
  const { user } = useAuthStore();

  // Estados principais de dados
  const [clients, setClients] = useState<Client[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Estados de UI
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Estado do formulário
  const [form, setForm] = useState({
    companyName: '',
    cnpj: '',
    serviceType: 'CONTABIL',
    monthlyFee: '',
    status: 'ATIVO',
    startDate: '',
    endDate: '',
    contactName: '',
    contactEmail: '',
    contactPhone: '',
    observations: '',
  });

  // 1. CARREGAR DADOS: Busca clientes e métricas ao abrir a página
  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [cliRes, metRes] = await Promise.all([
        api.get('/clients'),
        api.get('/clients/metrics'),
      ]);
      setClients(cliRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      console.error('Erro ao carregar dados:', err);
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados. Tente recarregar a página.');
      }
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAR: Busca em tempo real na tabela
  const filteredClients = clients.filter(
    (cli) =>
      cli.companyName.toLowerCase().includes(search.toLowerCase()) ||
      cli.contactName?.toLowerCase().includes(search.toLowerCase()) ||
      cli.serviceType.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO: Prepara o estado para criar ou editar
  function openForm(client?: Client) {
    if (client) {
      setEditingId(client.id);
      setForm({
        companyName: client.companyName,
        cnpj: client.cnpj || '',
        serviceType: client.serviceType,
        monthlyFee: client.monthlyFee.toString(),
        status: client.status,
        startDate: client.startDate.split('T')[0],
        endDate: client.endDate?.split('T')[0] || '',
        contactName: client.contactName || '',
        contactEmail: client.contactEmail || '',
        contactPhone: client.contactPhone || '',
        observations: client.observations || '',
      });
    } else {
      setEditingId(null);
      setForm({
        companyName: '',
        cnpj: '',
        serviceType: 'CONTABIL',
        monthlyFee: '',
        status: 'ATIVO',
        startDate: '',
        endDate: '',
        contactName: '',
        contactEmail: '',
        contactPhone: '',
        observations: '',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR: Envia para o backend (POST ou PUT)
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);

    try {
      const payload = {
        ...form,
        monthlyFee: form.monthlyFee ? parseFloat(form.monthlyFee) : 0,
        startDate: form.startDate,
        endDate: form.endDate || undefined,
      };

      if (editingId) {
        await api.put(`/clients/${editingId}`, payload);
      } else {
        await api.post('/clients', payload);
      }

      setShowForm(false);
      await loadData(); // Recarrega a tabela com os dados novos
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      alert('Erro ao salvar cliente. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER: Deleta o cliente
  async function handleDelete(id: string) {
    if (!confirm('Tem certeza que deseja remover este cliente?')) return;
    try {
      await api.delete(`/clients/${id}`);
      await loadData();
    } catch (err: any) {
      console.error('Erro ao remover:', err);
      alert('Erro ao remover cliente.');
    }
  }

  // TELA DE CARREGAMENTO
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // TELA DE ERRO
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // TELA PRINCIPAL
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Gestão de Clientes</h1>
          <p className="text-slate-600">Acompanhe sua carteira de clientes e faturamento</p>
        </div>
        <button
          onClick={() => openForm()}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors"
        >
          <Plus className="h-5 w-5" />
          Novo Cliente
        </button>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-8">
          <MetricCard icon={Briefcase} label="Total Ativos" value={metrics.totalActive} color="blue" />
          <MetricCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${metrics.monthlyRevenue.toFixed(2)}`} color="green" />
          <MetricCard icon={UserPlus} label="Novos (mês)" value={metrics.newClientsThisMonth} color="purple" />
          <MetricCard icon={TrendingUp} label="Ticket Médio" value={`R$ ${metrics.averageTicket.toFixed(2)}`} color="orange" />
          <MetricCard icon={Briefcase} label="Total Geral" value={metrics.totalClients} color="slate" />
        </div>
      )}

      {/* Barra de Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
