    observations: '',
  });

  // 1. CARREGAR DADOS: Busca precificações e métricas ao abrir a página
  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [priRes, metRes] = await Promise.all([
        api.get('/pricings'),
        api.get('/pricings/metrics'),
