  function openForm(pricing?: Pricing) {
    if (pricing) {
      setEditingId(pricing.id);
      setForm({
        title: pricing.title,
        serviceType: pricing.serviceType,
        complexity: pricing.complexity,
        estimatedHours: pricing.estimatedHours.toString(),
