'use client';

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import {
  Target,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
  CheckCircle,
  Clock,
  Calendar,
} from 'lucide-react';

// --- TIPOS (Para o TypeScript nos ajudar) ---
interface Planning {
  id: string;
  title: string;
  description: string;
  category: string;
  targetDate: string;
  status: string;
  progress: number;
}

interface Metrics {
  totalPlans: number;
  completedPlans: number;
  averageProgress: number;
}

export default function PlanejamentoPage() {
  const { user } = useAuthStore();

  // Estados principais de dados
  const [plannings, setPlannings] = useState<Planning[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Estados de UI
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Estado do formulário
  const [form, setForm] = useState({
    title: '',
    description: '',
    category: 'COMERCIAL',
    targetDate: '',
    status: 'PENDENTE',
    progress: '0',
  });

  // 1. CARREGAR DADOS: Busca planejamentos e métricas ao abrir a página
  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [planRes, metRes] = await Promise.all([
        api.get('/plannings'),
        api.get('/plannings/metrics'),
      ]);
      setPlannings(planRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      console.error('Erro ao carregar dados:', err);
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados. Tente recarregar a página.');
      }
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAR: Busca em tempo real na tabela
  const filteredPlannings = plannings.filter(
    (plan) =>
      plan.title.toLowerCase().includes(search.toLowerCase()) ||
      plan.category.toLowerCase().includes(search.toLowerCase()) ||
      plan.status.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO: Prepara o estado para criar ou editar
  function openForm(planning?: Planning) {
    if (planning) {
      setEditingId(planning.id);
      setForm({
        title: planning.title,
        description: planning.description || '',
        category: planning.category,
        targetDate: planning.targetDate.split('T')[0],
        status: planning.status,
        progress: planning.progress.toString(),
      });
    } else {
      setEditingId(null);
      setForm({
        title: '',
        description: '',
        category: 'COMERCIAL',
        targetDate: '',
        status: 'PENDENTE',
        progress: '0',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR: Envia para o backend (POST ou PUT)
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);

    try {
      const payload = {
        ...form,
        progress: parseFloat(form.progress) || 0,
        targetDate: form.targetDate,
      };

      if (editingId) {
        await api.put(`/plannings/${editingId}`, payload);
      } else {
        await api.post('/plannings', payload);
      }

      setShowForm(false);
      await loadData(); // Recarrega a tabela com os dados novos
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      alert('Erro ao salvar planejamento. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER: Deleta o planejamento
  async function handleDelete(id: string) {
    if (!confirm('Tem certeza que deseja remover este planejamento?')) return;
    try {
      await api.delete(`/plannings/${id}`);
      await loadData();
    } catch (err: any) {
      console.error('Erro ao remover:', err);
      alert('Erro ao remover planejamento.');
    }
  }

  // Função auxiliar para cor do status
  function getStatusColor(status: string) {
    switch (status) {
      case 'CONCLUIDO': return 'bg-green-100 text-green-800';
      case 'EM_ANDAMENTO': return 'bg-blue-100 text-blue-800';
      default: return 'bg-yellow-100 text-yellow-800';
    }
  }

  // TELA DE CARREGAMENTO
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // TELA DE ERRO
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // TELA PRINCIPAL
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho */}
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Planejamento Estratégico</h1>
          <p className="text-slate-600">Gerencie metas, objetivos e planos de ação do escritório</p>
        </div>
        <button
          onClick={() => openForm()}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors"
        >
          <Plus className="h-5 w-5" />
          Novo Planejamento
        </button>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
          <MetricCard icon={Target} label="Total de Metas" value={metrics.totalPlans} color="blue" />
          <MetricCard icon={CheckCircle} label="Metas Concluídas" value={metrics.completedPlans} color="green" />
          <MetricCard icon={Clock} label="Progresso Médio" value={`${metrics.averageProgress}%`} color="orange" />
        </div>
      )}

      {/* Barra de Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por título, categoria ou status..."
            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Tabela de Planejamentos */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredPlannings.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <Target className="h-12 w-12 mx-auto mb-4 text-slate-300" />
            <p className="text-lg font-medium">Nenhum planejamento cadastrado</p>
            <p className="text-sm mt-1">Clique em "Novo Planejamento" para começar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
