  // PROCESSA DADOS PARA O GRÁFICO DE PIZZA (Clientes por Tipo)
  // =================================================================
  const clientServiceData = (() => {
    const count: Record<string, number> = {};
    clients.forEach((c) => {
      if (c.status === 'ATIVO') {
        count[c.serviceType] = (count[c.serviceType] || 0) + 1;
      }
