  })();

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6'];
  const workforceData = [{ name: 'Este Mês', Admissões: employeeMetrics?.admissionsThisMonth || 0, Demissões: employeeMetrics?.dismissalsThisMonth || 0 }];

  if (loading) return <div className="flex items-center justify-center h-96"><Loader2 className="h-12 w-12 text-blue-600 animate-spin" /></div>;
  if (error) return <div className="flex items-center justify-center h-96"><AlertCircle className="h-12 w-12 text-red-500" /><p className="ml-2">{error}</p></div>;

  return (
