        <KpiCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${(clientMetrics?.monthlyRevenue || 0).toFixed(2)}`} trend={`Ticket: R$ ${(clientMetrics?.averageTicket || 0).toFixed(2)}`} color="green" />
        <KpiCard icon={Users} label="Colaboradores" value={employeeMetrics?.totalActive || 0} trend={`Turnover: ${employeeMetrics?.turnoverRate || 0}%`} color="purple" />
        <KpiCard icon={Target} label="Metas" value={planningMetrics?.totalPlans || 0} trend={`${planningMetrics?.completedPlans || 0} concluídas`} color="orange" />
      </div>

      {/* Gráficos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Carteira por Tipo de Serviço</h3>
          {clientServiceData.length > 0 ? (
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie data={clientServiceData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={3} dataKey="value">
                  {clientServiceData.map((_, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip />
