### 🔍 **POR QUE O GRÁFICO DE PIZZA NÃO APARECE?**

Isso é um **bug conhecido do `ResponsiveContainer` do Recharts** quando usado com o **Next.js App Router (versões 13+)**. 

O Next.js tenta renderizar a página no servidor (SSR) antes de enviar para o navegador. O `ResponsiveContainer` do Recharts tenta calcular a largura e altura do elemento pai, mas como no servidor não existe uma "tela" real, ele calcula `0px` e o gráfico fica invisível.

### ✅ **A SOLUÇÃO DEFINITIVA: Renderizar apenas no Navegador**

Vamos envolver os gráficos em um componente "mágico" chamado `ClientOnly`. Ele garante que o Recharts só tente desenhar os gráficos **depois** que a página já estiver carregada no seu navegador, onde as dimensões da tela existem.

Substitua **todo** o conteúdo do arquivo `frontend/src/app/dashboard/page.tsx` por este código corrigido:

```typescript
'use client';

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import { Briefcase, DollarSign, Users, Target, Loader2, AlertCircle } from 'lucide-react';
import {
  PieChart, Pie, Cell, BarChart, Bar, XAxis, YAxis,
  CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';

// =================================================================
// COMPONENTE MÁGICO: Só renderiza os filhos no Navegador (Client-Side)
// Isso resolve o bug do Recharts com o SSR do Next.js App Router
// =================================================================
function ClientOnly({ children }: { children: React.ReactNode }) {
  const [hasMounted, setHasMounted] = useState(false);
  useEffect(() => { setHasMounted(true); }, []);
  if (!hasMounted) {
    return <div className="h-[300px] flex items-center justify-center text-slate-400 text-sm">Carregando gráfico...</div>;
  }
  return <>{children}</>;
}

export default function DashboardPage() {
  const { user } = useAuthStore();
  const [clientMetrics, setClientMetrics] = useState<any>(null);
  const [employeeMetrics, setEmployeeMetrics] = useState<any>(null);
  const [pricingMetrics, setPricingMetrics] = useState<any>(null);
  const [planningMetrics, setPlanningMetrics] = useState<any>(null);
  const [clients, setClients] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => { loadData(); }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [cliRes, empRes, priRes, plaRes, clientsRes] = await Promise.all([
        api.get('/clients/metrics'),
        api.get('/employees/metrics'),
        api.get('/pricings/metrics'),
        api.get('/plannings/metrics'),
        api.get('/clients'),
      ]);
      setClientMetrics(cliRes.data.data || null);
      setEmployeeMetrics(empRes.data.data || null);
      setPricingMetrics(priRes.data.data || null);
      setPlanningMetrics(plaRes.data.data || null);
      setClients(clientsRes.data.data || []);
    } catch (err: any) {
      if (err.response?.status !== 401) setError('Erro ao carregar dados do dashboard.');
    } finally {
      setLoading(false);
    }
  }

  // Prepara dados para o gráfico de pizza
  const clientServiceData = (() => {
    const count: Record<string, number> = {};
    (clients || []).forEach((c: any) => {
      const status = (c.status || '').toUpperCase();
      if (status.includes('ATIVO') || status === 'ACTIVE') {
        const type = c.serviceType || 'Outro';
        count[type] = (count[type] || 0) + 1;
      }
    });
    return Object.entries(count).map(([name, value]) => ({ name, value }));
  })();

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444'];

  const workforceData = [
    { 
      name: 'Este Mês', 
      Admissões: employeeMetrics?.admissionsThisMonth || 0, 
      Demissões: employeeMetrics?.dismissalsThisMonth || 0 
    }
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-12 w-12 text-blue-600 animate-spin" />
        <span className="ml-3 text-slate-600 font-medium">Carregando painel...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-96">
        <AlertCircle className="h-12 w-12 text-red-500" />
        <p className="ml-3 text-slate-700">{error}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div>
        <h1 className="text-3xl font-bold text-slate-900">Visão Geral</h1>
        <p className="text-slate-600">Resumo executivo do seu escritório.</p>
      </div>

      {/* KPIs Principais */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard icon={Briefcase} label="Clientes Ativos" value={clientMetrics?.totalActive || 0} trend={`${clientMetrics?.newClientsThisMonth || 0} novos`} color="blue" />
        <KpiCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${(clientMetrics?.monthlyRevenue || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} trend={`Ticket: R$ ${(clientMetrics?.averageTicket || 0).toFixed(2)}`} color="green" />
        <KpiCard icon={Users} label="Colaboradores" value={employeeMetrics?.totalActive || 0} trend={`Turnover: ${employeeMetrics?.turnoverRate || 0}%`} color="purple" />
        <KpiCard icon={Target} label="Metas" value={planningMetrics?.totalPlans || 0} trend={`${planningMetrics?.completedPlans || 0} concluídas`} color="orange" />
      </div>

      {/* Gráficos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Gráfico de Pizza */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Carteira por Tipo de Serviço</h3>
          {clientServiceData.length > 0 ? (
            // 🔥 AQUI ESTÁ A CORREÇÃO: Envolvemos o gráfico no ClientOnly
            <ClientOnly>
              <ResponsiveContainer width="100%" height={300}>
                <PieChart>
                  <Pie 
                    data={clientServiceData} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={60} 
                    outerRadius={100} 
                    paddingAngle={3} 
                    dataKey="value"
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                  >
                    {clientServiceData.map((_, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </ClientOnly>
          ) : (
            <div className="h-[300px] flex flex-col items-center justify-center text-slate-400">
              <Briefcase className="h-10 w-10 mb-2 opacity-50" />
              <p>Nenhum cliente com status "Ativo" encontrado na lista.</p>
            </div>
          )}
        </div>

        {/* Gráfico de Barras */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Movimentação de Pessoal</h3>
