            <div className="h-[300px] flex flex-col items-center justify-center text-slate-400">
              <Users className="h-10 w-10 mb-2 opacity-50" />
              <p>Nenhuma admissão ou demissão registrada este mês.</p>
              <p className="text-xs mt-1 text-center max-w-xs">(O gráfico só aparece quando houver movimentação de pessoal no mês atual)</p>
            </div>
          ) : (
            // 🔥 AQUI TAMBÉM: Envolvemos no ClientOnly
            <ClientOnly>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={workforceData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" stroke="#64748b" />
                  <YAxis stroke="#64748b" />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="Admissões" fill="#10b981" radius={[8, 8, 0, 0]} />
                  <Bar dataKey="Demissões" fill="#ef4444" radius={[8, 8, 0, 0]} />
