### 🔧 **SOLUÇÃO DEFINITIVA: Dynamic Import com `ssr: false`**

Substitua **TODO** o conteúdo do arquivo `frontend/src/app/dashboard/page.tsx` por este código. 

A grande mudança aqui é que estamos importando os componentes do Recharts de forma dinâmica, garantindo que eles só existam no lado do cliente (Browser).

```typescript
'use client';

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import { Briefcase, DollarSign, Users, Target, Loader2, AlertCircle } from 'lucide-react';
import dynamic from 'next/dynamic';

// =================================================================
// IMPORTAÇÃO DINÂMICA (A SOLUÇÃO MÁGICA)
// Isso impede que o Recharts tente renderizar no servidor (SSR), 
// evitando o bug de altura 0px e tela em branco.
// =================================================================
const ResponsiveContainer = dynamic(() => import('recharts').then(mod => mod.ResponsiveContainer), { ssr: false });
const PieChart = dynamic(() => import('recharts').then(mod => mod.PieChart), { ssr: false });
const Pie = dynamic(() => import('recharts').then(mod => mod.Pie), { ssr: false });
const Cell = dynamic(() => import('recharts').then(mod => mod.Cell), { ssr: false });
const Tooltip = dynamic(() => import('recharts').then(mod => mod.Tooltip), { ssr: false });
const Legend = dynamic(() => import('recharts').then(mod => mod.Legend), { ssr: false });

const BarChart = dynamic(() => import('recharts').then(mod => mod.BarChart), { ssr: false });
const Bar = dynamic(() => import('recharts').then(mod => mod.Bar), { ssr: false });
const XAxis = dynamic(() => import('recharts').then(mod => mod.XAxis), { ssr: false });
const YAxis = dynamic(() => import('recharts').then(mod => mod.YAxis), { ssr: false });
const CartesianGrid = dynamic(() => import('recharts').then(mod => mod.CartesianGrid), { ssr: false });

export default function DashboardPage() {
  const { user } = useAuthStore();
  const [clientMetrics, setClientMetrics] = useState<any>(null);
  const [employeeMetrics, setEmployeeMetrics] = useState<any>(null);
  const [pricingMetrics, setPricingMetrics] = useState<any>(null);
  const [planningMetrics, setPlanningMetrics] = useState<any>(null);
  const [clients, setClients] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [cliRes, empRes, priRes, plaRes, clientsRes] = await Promise.all([
        api.get('/clients/metrics'),
        api.get('/employees/metrics'),
        api.get('/pricings/metrics'),
        api.get('/plannings/metrics'),
        api.get('/clients'),
      ]);

      const cliData = cliRes.data.data || null;
      const empData = empRes.data.data || null;
      const clientsData = clientsRes.data.data || [];

      setClientMetrics(cliData);
      setEmployeeMetrics(empData);
      setPricingMetrics(priRes.data.data || null);
      setPlanningMetrics(plaRes.data.data || null);
      setClients(clientsData);

    } catch (err: any) {
      console.error('Erro ao carregar dashboard:', err);
      if (err.response?.status !== 401) setError('Erro ao carregar dados do dashboard.');
    } finally {
      setLoading(false);
    }
  }

  // Prepara dados para o gráfico de pizza
  const clientServiceData = (() => {
    const count: Record<string, number> = {};
    (clients || []).forEach((c: any) => {
      const status = (c.status || '').toUpperCase();
      if (status.includes('ATIVO') || status === 'ACTIVE') {
        const type = c.serviceType || 'Outro';
        count[type] = (count[type] || 0) + 1;
      }
    });
    return Object.entries(count).map(([name, value]) => ({ name, value }));
  })();

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ef4444'];

  const workforceData = [
    { 
      name: 'Este Mês', 
      Admissões: employeeMetrics?.admissionsThisMonth || 0, 
      Demissões: employeeMetrics?.dismissalsThisMonth || 0 
    }
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-12 w-12 text-blue-600 animate-spin" />
        <span className="ml-3 text-slate-600 font-medium">Carregando painel...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center h-96">
        <AlertCircle className="h-12 w-12 text-red-500" />
        <p className="ml-3 text-slate-700">{error}</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div>
        <h1 className="text-3xl font-bold text-slate-900">Visão Geral</h1>
        <p className="text-slate-600">Resumo executivo do seu escritório.</p>
      </div>

      {/* KPIs Principais */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard icon={Briefcase} label="Clientes Ativos" value={clientMetrics?.totalActive || 0} trend={`${clientMetrics?.newClientsThisMonth || 0} novos`} color="blue" />
        <KpiCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${(clientMetrics?.monthlyRevenue || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} trend={`Ticket: R$ ${(clientMetrics?.averageTicket || 0).toFixed(2)}`} color="green" />
        <KpiCard icon={Users} label="Colaboradores" value={employeeMetrics?.totalActive || 0} trend={`Turnover: ${employeeMetrics?.turnoverRate || 0}%`} color="purple" />
        <KpiCard icon={Target} label="Metas" value={planningMetrics?.totalPlans || 0} trend={`${planningMetrics?.completedPlans || 0} concluídas`} color="orange" />
      </div>

      {/* Gráficos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Gráfico de Pizza */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Carteira por Tipo de Serviço</h3>
          {clientServiceData.length > 0 ? (
            <div className="w-full" style={{ height: '300px' }}>
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie 
                    data={clientServiceData} 
                    cx="50%" 
                    cy="50%" 
                    innerRadius={60} 
                    outerRadius={100} 
                    paddingAngle={3} 
                    dataKey="value"
                    label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                  >
                    {clientServiceData.map((_, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <div className="h-[300px] flex flex-col items-center justify-center text-slate-400">
              <Briefcase className="h-10 w-10 mb-2 opacity-50" />
              <p>Nenhum cliente com status "Ativo" encontrado.</p>
            </div>
          )}
        </div>

        {/* Gráfico de Barras */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Movimentação de Pessoal</h3>
          {workforceData[0].Admissões === 0 && workforceData[0].Demissões === 0 ? (
            <div className="h-[300px] flex flex-col items-center justify-center text-slate-400">
              <Users className="h-10 w-10 mb-2 opacity-50" />
              <p>Nenhuma admissão ou demissão registrada este mês.</p>
            </div>
          ) : (
            <div className="w-full" style={{ height: '300px' }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={workforceData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="name" stroke="#64748b" />
                  <YAxis stroke="#64748b" />
                  <Tooltip />
                  <Legend />
                  <Bar dataKey="Admissões" fill="#10b981" radius={[8, 8, 0, 0]} />
                  <Bar dataKey="Demissões" fill="#ef4444" radius={[8, 8, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// Componente auxiliar de KPI
function KpiCard({ icon: Icon, label, value, trend, color }: any) {
  const colors: any = { 
    blue: 'bg-blue-100 text-blue-600', 
    green: 'bg-green-100 text-green-600', 
    purple: 'bg-purple-100 text-purple-600', 
    orange: 'bg-orange-100 text-orange-600' 
  };
  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
      <div className={`w-12 h-12 rounded-lg ${colors[color]} flex items-center justify-center mb-4`}>
        <Icon className="h-6 w-6" />
      </div>
      <div className="text-3xl font-bold text-slate-900 mb-1">{value}</div>
      <div className="text-sm font-medium text-slate-600">{label}</div>
      <div className="text-xs text-slate-500 mt-1">{trend}</div>
    </div>
  );
}
