  }

  return (
    // Div pai com altura explícita para o ResponsiveContainer funcionar
    <div style={{ width: '100%', height: '300px' }}>
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={data}
