        <p>Nenhum dado disponível para o gráfico.</p>
      </div>
    );
  }

  return (
    <div className="w-full flex items-center justify-center border-2 border-dashed border-blue-300 rounded-lg overflow-hidden py-4">
      {/* 
        SOLUÇÃO: Removemos o ResponsiveContainer. 
        No Next.js App Router, ele frequentemente falha ao calcular a altura no SSR, 
        resultando em um gráfico de 0px (tela em branco). 
        Usar dimensões fixas (width/height) garante a renderização imediata e visível.
      */}
      <PieChart width={400} height={300}>
        <Pie
          data={data}
          cx="50%"
          cy="50%"
          innerRadius={60}
          outerRadius={100}
          paddingAngle={3}
          dataKey="value"
        >
          {data.map((entry, index) => (
            <Cell 
              key={`cell-${index}`} 
              fill={COLORS[index % COLORS.length]} 
              stroke="#ffffff" 
              strokeWidth={2} 
            />
          ))}
        </Pie>
        <Tooltip 
          contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }}
        />
        <Legend />
      </PieChart>
