}

export function BarChartComponent({ data }: { data: any[] }) {
  return (
    <div className="w-full flex items-center justify-center border-2 border-dashed border-blue-300 rounded-lg overflow-hidden py-4">
      <BarChart width={500} height={300} data={data}>
        <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
        <XAxis dataKey="name" stroke="#64748b" />
        <YAxis stroke="#64748b" />
        <Tooltip contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0' }} />
        <Legend />
        <Bar dataKey="Admissões" fill="#10b981" radius={[8, 8, 0, 0]} />
