                      <button onClick={() => handleDelete(cli.id)} className="text-red-600 hover:text-red-800" title="Remover">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
