  // --- ESTADOS DE DADOS ---
  const [clients, setClients] = useState<Client[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // --- ESTADOS DE UI E FORMULÁRIO ---
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [form, setForm] = useState({
    companyName: '', cnpj: '', serviceType: 'CONTABIL', monthlyFee: '',
    status: 'ATIVO', startDate: '', endDate: '', contactName: '',
    contactEmail: '', contactPhone: '', observations: '',
  });

  // 1. CARREGAR DADOS INICIAIS
  useEffect(() => { loadData(); }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [cliRes, metRes] = await Promise.all([
        api.get('/clients'),
        api.get('/clients/metrics'),
      ]);
      setClients(cliRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      if (err.response?.status !== 401) setError('Erro ao carregar dados.');
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAGEM INTELIGENTE (Busca em tempo real)
  const filteredClients = clients.filter((cli) =>
    cli.companyName.toLowerCase().includes(search.toLowerCase()) ||
    cli.contactName?.toLowerCase().includes(search.toLowerCase()) ||
    cli.serviceType.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO (Modo Criar ou Editar)
  function openForm(client?: Client) {
    if (client) {
      setEditingId(client.id);
      setForm({
        companyName: client.companyName, cnpj: client.cnpj || '',
        serviceType: client.serviceType, monthlyFee: client.monthlyFee.toString(),
        status: client.status, startDate: client.startDate.split('T')[0],
        endDate: client.endDate?.split('T')[0] || '', contactName: client.contactName || '',
        contactEmail: client.contactEmail || '', contactPhone: client.contactPhone || '',
        observations: client.observations || '',
      });
    } else {
      setEditingId(null);
      setForm({
        companyName: '', cnpj: '', serviceType: 'CONTABIL', monthlyFee: '',
        status: 'ATIVO', startDate: '', endDate: '', contactName: '',
        contactEmail: '', contactPhone: '', observations: '',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR (POST ou PUT) - COM TOASTS
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      const payload = {
        ...form,
        monthlyFee: parseFloat(form.monthlyFee) || 0,
        startDate: form.startDate,
        endDate: form.endDate || undefined,
      };
      if (editingId) await api.put(`/clients/${editingId}`, payload);
      else await api.post('/clients', payload);

      // Substitui o alert() por um Toast de Sucesso elegante
      toast.success(editingId ? 'Cliente atualizado com sucesso!' : 'Cliente criado com sucesso!');

      setShowForm(false);
      await loadData();
    } catch (err) {
      // Substitui o alert() de erro por um Toast de Erro
      toast.error('Erro ao salvar cliente. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER (DELETE) - COM TOAST DE CONFIRMAÇÃO
  function handleDelete(id: string) {
    // Substitui o confirm() nativo por um Toast interativo com botões de ação
    toast('Tem certeza que deseja remover este cliente?', {
      action: {
        label: 'Sim, excluir',
        onClick: async () => {
          try {
            await api.delete(`/clients/${id}`);
            toast.success('Cliente removido com sucesso!');
            await loadData();
          } catch (err) {
            toast.error('Erro ao remover cliente.');
          }
        },
      },
      cancel: {
        label: 'Cancelar',
        onClick: () => {},
      },
    });
  }

  // 6. EXPORTAR PARA CSV (Lógica Inteligente)
  function handleExport() {
    const dataToExport = search.trim() !== '' ? filteredClients : clients;
    exportToCSV(dataToExport, 'carteira_de_clientes');
    toast.success('Relatório exportado com sucesso!'); // Feedback visual do download
  }

  // --- RENDERIZAÇÃO: TELA DE CARREGAMENTO ---
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA DE ERRO ---
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA PRINCIPAL ---
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho com Ações */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Gestão de Clientes</h1>
          <p className="text-slate-600">Acompanhe sua carteira de clientes e faturamento</p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Download className="h-5 w-5" />
            Exportar CSV
          </button>
          <button
            onClick={() => openForm()}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Plus className="h-5 w-5" />
            Novo Cliente
          </button>
        </div>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-8">
          <MetricCard icon={Briefcase} label="Total Ativos" value={metrics.totalActive} color="blue" />
          <MetricCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${metrics.monthlyRevenue.toFixed(2)}`} color="green" />
          <MetricCard icon={UserPlus} label="Novos (mês)" value={metrics.newClientsThisMonth} color="purple" />
          <MetricCard icon={TrendingUp} label="Ticket Médio" value={`R$ ${metrics.averageTicket.toFixed(2)}`} color="orange" />
          <MetricCard icon={Briefcase} label="Total Geral" value={metrics.totalClients} color="slate" />
        </div>
      )}

      {/* Barra de Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por empresa, contato ou tipo de serviço..."
            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Tabela de Clientes */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredClients.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <Briefcase className="h-12 w-12 mx-auto mb-4 text-slate-300" />
            <p className="text-lg font-medium">Nenhum cliente encontrado</p>
            <p className="text-sm mt-1">Clique em "Novo Cliente" para começar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Empresa</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Serviço</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Honorário</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Status</th>
                  <th className="text-right px-6 py-3 text-xs font-medium text-slate-500 uppercase">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {filteredClients.map((cli) => (
                  <tr key={cli.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-900">{cli.companyName}</div>
