                    </td>
                    <td className="px-6 py-4 text-slate-700">{cli.serviceType}</td>
                    <td className="px-6 py-4 text-slate-700">R$ {cli.monthlyFee.toFixed(2)}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        cli.status === 'ATIVO' ? 'bg-green-100 text-green-800' : 
