```typescript
'use client';

/**
 * =================================================================
 * MÓDULO DE PLANEJAMENTO ESTRATÉGICO (VERSÃO FINAL COM TOASTS)
 * =================================================================
 * 
 * Este arquivo gerencia o CRUD (Criar, Ler, Atualizar, Deletar) 
 * de metas e objetivos estratégicos do escritório.
 * 
 * CARACTERÍSTICAS PROFISSIONAIS:
 * - Integração com Zustand para autenticação.
 * - Cálculo de métricas de progresso e conclusão.
 * - Exportação CSV para relatórios de acompanhamento.
 * - Notificações Toast elegantes (sonner) substituindo alert() e confirm().
 * - Barras de progresso visuais para acompanhamento de metas.
 */

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import { exportToCSV } from '@/lib/exportToCSV';
import { toast } from 'sonner'; // <-- NOSSO SISTEMA DE NOTIFICAÇÕES
import {
  Target,
  CheckCircle,
  Clock,
  Calendar,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
  Download,
} from 'lucide-react';

// --- TIPOS (TypeScript) ---
interface Planning {
  id: string;
  title: string;
  description: string;
  category: string;
  targetDate: string;
  status: string;
  progress: number;
}

interface Metrics {
  totalPlans: number;
  completedPlans: number;
  averageProgress: number;
}

export default function PlanejamentoPage() {
  const { user } = useAuthStore();

  // --- ESTADOS DE DADOS ---
  const [plannings, setPlannings] = useState<Planning[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // --- ESTADOS DE UI E FORMULÁRIO ---
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [form, setForm] = useState({
    title: '', description: '', category: 'COMERCIAL',
    targetDate: '', status: 'PENDENTE', progress: '0',
  });

  // 1. CARREGAR DADOS INICIAIS
  useEffect(() => { loadData(); }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [planRes, metRes] = await Promise.all([
        api.get('/plannings'),
        api.get('/plannings/metrics'),
      ]);
      setPlannings(planRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados.');
        toast.error('Falha ao carregar dados de planejamento');
      }
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAGEM INTELIGENTE (Busca em tempo real)
  const filteredPlannings = plannings.filter((plan) =>
    plan.title.toLowerCase().includes(search.toLowerCase()) ||
    plan.category.toLowerCase().includes(search.toLowerCase()) ||
    plan.status.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO (Modo Criar ou Editar)
  function openForm(planning?: Planning) {
    if (planning) {
      setEditingId(planning.id);
      setForm({
        title: planning.title, description: planning.description || '',
        category: planning.category,
        targetDate: planning.targetDate.split('T')[0],
        status: planning.status, progress: planning.progress.toString(),
      });
    } else {
      setEditingId(null);
      setForm({
        title: '', description: '', category: 'COMERCIAL',
        targetDate: '', status: 'PENDENTE', progress: '0',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR (POST ou PUT) COM TOASTS
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      const payload = {
        ...form,
        progress: parseFloat(form.progress) || 0,
        targetDate: form.targetDate,
      };

      if (editingId) {
        await api.put(`/plannings/${editingId}`, payload);
        toast.success('Planejamento atualizado com sucesso!');
      } else {
        await api.post('/plannings', payload);
        toast.success('Planejamento criado com sucesso!');
      }

      setShowForm(false);
      await loadData();
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      toast.error('Erro ao salvar planejamento. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER (DELETE) COM TOAST INTERATIVO
  function handleDelete(id: string) {
    toast('Tem certeza que deseja remover este planejamento?', {
      description: 'Esta ação não pode ser desfeita.',
      action: {
        label: 'Remover',
        onClick: async () => {
          try {
            await api.delete(`/plannings/${id}`);
            toast.success('Planejamento removido com sucesso!');
            await loadData();
          } catch (err) {
            toast.error('Erro ao remover planejamento.');
          }
        },
      },
      cancel: {
        label: 'Cancelar',
      },
      style: {
        background: '#ffffff',
        color: '#0f172a',
        border: '1px solid #e2e8f0',
      },
    });
  }

  // 6. EXPORTAR PARA CSV (Lógica Inteligente)
  function handleExport() {
    const dataToExport = search.trim() !== '' ? filteredPlannings : plannings;

    if (dataToExport.length === 0) {
      toast.warning('Nenhum dado disponível para exportar');
      return;
    }

    exportToCSV(dataToExport, 'planejamento_estrategico');
    toast.success(`${dataToExport.length} meta(s) exportada(s) com sucesso!`);
  }

  // Função auxiliar para cor do status
  function getStatusColor(status: string) {
    switch (status) {
      case 'CONCLUIDO': return 'bg-green-100 text-green-800';
      case 'EM_ANDAMENTO': return 'bg-blue-100 text-blue-800';
      default: return 'bg-yellow-100 text-yellow-800';
    }
  }

  // --- RENDERIZAÇÃO: TELA DE CARREGAMENTO ---
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA DE ERRO ---
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA PRINCIPAL ---
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho com Ações */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Planejamento Estratégico</h1>
          <p className="text-slate-600">Gerencie metas, objetivos e planos de ação do escritório</p>
        </div>
        <div className="flex gap-3">
          {/* Botão de Exportação */}
          <button
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Download className="h-5 w-5" />
            Exportar CSV
          </button>
          {/* Botão de Novo Planejamento */}
          <button
            onClick={() => openForm()}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Plus className="h-5 w-5" />
            Novo Planejamento
          </button>
        </div>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
          <MetricCard icon={Target} label="Total de Metas" value={metrics.totalPlans} color="blue" />
          <MetricCard icon={CheckCircle} label="Metas Concluídas" value={metrics.completedPlans} color="green" />
          <MetricCard icon={Clock} label="Progresso Médio" value={`${metrics.averageProgress}%`} color="orange" />
        </div>
      )}

      {/* Barra de Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por título, categoria ou status..."
            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Tabela de Planejamentos */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredPlannings.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <Target className="h-12 w-12 mx-auto mb-4 text-slate-300" />
            <p className="text-lg font-medium">Nenhum planejamento cadastrado</p>
            <p className="text-sm mt-1">Clique em "Novo Planejamento" para começar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Meta / Objetivo</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Categoria</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Prazo</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Progresso</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Status</th>
                  <th className="text-right px-6 py-3 text-xs font-medium text-slate-500 uppercase">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {filteredPlannings.map((plan) => (
                  <tr key={plan.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-900">{plan.title}</div>
