                          ></div>
                        </div>
                        <span className="text-sm text-slate-600">{plan.progress}%</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${getStatusColor(plan.status)}`}>
                        {plan.status.replace('_', ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button onClick={() => openForm(plan)} className="text-blue-600 hover:text-blue-800 mr-3" title="Editar">
                        <Edit2 className="h-4 w-4" />
