### 📄 **ARQUIVO 2: `frontend/src/app/dashboard/layout.tsx`**

**Problema:** Redirecionava para `/login` antes da hidratação terminar.
**Solução:** Agora espera `isHydrated === true` antes de verificar o login.

```typescript
'use client';

/**
 * Layout do Dashboard - Protege todas as rotas /dashboard/*
 * 
 * COMO FUNCIONA A PROTEÇÃO:
 * 1. Aguarda o Zustand terminar de ler o localStorage (isHydrated)
 * 2. Se NÃO está logado (user === null) → redireciona para /login
 * 3. Se está logado → renderiza o dashboard normalmente
 * 
 * POR QUE ESPERAR A HIDRATAÇÃO?
 * - Sem isso, o user seria null por alguns milissegundos
 * - O layout pensaria que não está logado e redirecionaria erroneamente
 * - Isso causava o bug de "pedir login ao navegar entre páginas"
 */

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuthStore } from '@/store/authStore';
import {
  LayoutDashboard,
  Users,
  Building2,
  DollarSign,
  Target,
  LogOut,
  Menu,
  X,
} from 'lucide-react';
import { useState } from 'react';

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const { user, token, isHydrated, logout } = useAuthStore();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  /**
   * EFEITO 1: Proteção de rota
   * 
   * DEPENDÊNCIAS: [isHydrated, user, router]
   * - Só executa DEPOIS que isHydrated === true
   * - Se user for null (e já hidratou) → não está logado → vai para /login
   */
  useEffect(() => {
    // NÃO FAÇA NADA até a hidratação terminar
    if (!isHydrated) return;

    // Se hidratou e NÃO tem user → redireciona para login
    if (!user || !token) {
      router.push('/login');
    }
  }, [isHydrated, user, token, router]);

  /**
   * EFEITO 2: Fecha sidebar ao mudar de rota (mobile)
   */
  useEffect(() => {
    setSidebarOpen(false);
  }, [router]);

  /**
   * Função de logout
   * Limpa o store e redireciona para /login
   */
  const handleLogout = () => {
    logout();
    router.push('/login');
  };

  /**
   * SE AINDA NÃO HIDRATOU: mostra tela de loading
   * Isso evita o "flash" de redirecionamento falso
   */
  if (!isHydrated) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-slate-600">Carregando...</p>
        </div>
      </div>
    );
  }

  /**
   * SE NÃO ESTÁ LOGADO: não renderiza nada (o useEffect já vai redirecionar)
   */
  if (!user || !token) {
    return null;
  }

  // Menu de navegação do dashboard
  const menuItems = [
    { href: '/dashboard', label: 'Visão Geral', icon: LayoutDashboard },
    { href: '/dashboard/minha-empresa', label: 'Minha Empresa', icon: Building2 },
    { href: '/dashboard/pessoas', label: 'Gestão de Pessoas', icon: Users },
    { href: '/dashboard/precificacao', label: 'Precificação', icon: DollarSign },
    { href: '/dashboard/planejamento', label: 'Planejamento', icon: Target },
  ];

  return (
    <div className="min-h-screen bg-slate-50">
      {/* Sidebar - Desktop */}
      <aside className="fixed left-0 top-0 h-full w-64 bg-slate-900 text-white z-40 hidden lg:block">
        <div className="p-6 border-b border-slate-700">
          <h1 className="text-xl font-bold">Radar Clone</h1>
          <p className="text-sm text-slate-400">Gestão Empresarial</p>
        </div>

        <nav className="p-4 space-y-1">
          {menuItems.map((item) => {
            const Icon = item.icon;
            return (
              <a
                key={item.href}
                href={item.href}
                className="flex items-center gap-3 px-4 py-3 rounded-lg hover:bg-slate-800 transition-colors"
              >
                <Icon className="h-5 w-5" />
                <span>{item.label}</span>
              </a>
            );
          })}
        </nav>

        <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-slate-700">
          <div className="mb-3 px-4">
            <p className="text-sm font-medium truncate">{user.name}</p>
            <p className="text-xs text-slate-400 truncate">{user.email}</p>
          </div>
          <button
            onClick={handleLogout}
            className="flex items-center gap-3 px-4 py-2 w-full rounded-lg hover:bg-slate-800 transition-colors text-red-400"
          >
            <LogOut className="h-5 w-5" />
            <span>Sair</span>
          </button>
