 * 
 * POR QUE USAR INTERFACES?
 * - O TypeScript valida os dados em tempo de compilação
 * - Autocomplete no VS Code
 * - Evita erros de digitação em nomes de campos
 */
interface Employee {
  id: string;
  name: string;
  email: string;
  phone: string;
  position: string;
  department: string;
  admissionDate: string;
  dismissalDate: string | null;
  salary: number;
  status: string;
}

interface Metrics {
  totalActive: number;
  totalEmployees: number;
  admissionsThisMonth: number;
  dismissalsThisMonth: number;
  turnoverRate: number;
}

export default function PessoasPage() {
  const { user } = useAuthStore();

  // Estados principais de dados
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Estados de UI
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Estado do formulário
  const [form, setForm] = useState({
    name: '',
    email: '',
    phone: '',
    position: '',
    department: '',
    admissionDate: '',
    dismissalDate: '',
    salary: '',
  });

  /**
   * CARREGA OS DADOS AO ABRIR A PÁGINA
   * 
   * POR QUE USAR Promise.all?
   * - Faz as duas requisições AO MESMO TEMPO (paralelo)
   * - Mais rápido que fazer uma depois da outra (sequencial)
   * - Se uma falhar, a outra ainda pode funcionar
   */
  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);

      const [empRes, metRes] = await Promise.all([
        api.get('/employees'),
        api.get('/employees/metrics'),
      ]);

      setEmployees(empRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      console.error('Erro ao carregar dados:', err);

      // Se foi erro 401, o interceptor do axios já fez logout
      // Não precisamos mostrar erro aqui
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados. Tente recarregar a página.');
      }
    } finally {
      setLoading(false);
    }
  }

  /**
   * FILTRA COLABORADORES PELA BUSCA
   * 
   * Executa em tempo real conforme o usuário digita
   * Busca em: nome, cargo e departamento
   */
  const filteredEmployees = employees.filter(
    (emp) =>
      emp.name.toLowerCase().includes(search.toLowerCase()) ||
      emp.position.toLowerCase().includes(search.toLowerCase()) ||
      emp.department?.toLowerCase().includes(search.toLowerCase()),
  );

  /**
   * ABRE O FORMULÁRIO (criar ou editar)
   * 
   * Se passar um employee → modo edição (preenche os campos)
   * Se não passar → modo criação (campos vazios)
   */
  function openForm(employee?: Employee) {
    if (employee) {
      setEditingId(employee.id);
      setForm({
        name: employee.name,
        email: employee.email || '',
        phone: employee.phone || '',
        position: employee.position,
        department: employee.department || '',
        admissionDate: employee.admissionDate.split('T')[0],
        dismissalDate: employee.dismissalDate?.split('T')[0] || '',
        salary: employee.salary?.toString() || '',
      });
    } else {
      setEditingId(null);
      setForm({
        name: '',
        email: '',
