## 📄 **ARQUIVO 1: `frontend/src/store/authStore.ts`**

**Versão final consolidada** (com hidratação para evitar redirecionamento falso):

```typescript
import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';

/**
 * Interface que define a forma dos dados do usuário autenticado
 */
interface User {
  id: string;
  name: string;
  email: string;
  role: string;
}

/**
 * Interface do estado global de autenticação
 * - user: dados do usuário logado (null se não logado)
 * - token: JWT para autenticar requisições (null se não logado)
 * - isHydrated: TRUE quando o Zustand já leu o localStorage
 *               (evita redirecionamento falso para /login)
 */
interface AuthState {
  user: User | null;
  token: string | null;
  isHydrated: boolean;

  // Ações
  setUser: (user: User, token: string) => void;
  logout: () => void;
  setHydrated: (state: boolean) => void;
}

/**
 * Store de autenticação com persistência no localStorage
 * 
 * POR QUE USAMOS 'createJSONStorage(() => localStorage)'?
 * - Garante que o Zustand só leia do localStorage no browser (não no SSR do Next.js)
 * - Evita erros de "window is not defined" durante a build
 */
export const useAuthStore = create<AuthState>()(
  persist(
    (set) => ({
      // Valores iniciais (antes da hidratação)
      user: null,
      token: null,
      isHydrated: false,

      /**
       * Salva o usuário e token após login bem-sucedido
       * O 'persist' middleware automaticamente grava no localStorage
       */
      setUser: (user, token) =>
        set({ user, token }),

      /**
       * Limpa todos os dados e faz logout
       */
      logout: () =>
        set({ user: null, token: null }),

      /**
       * Marca que a hidratação do localStorage terminou
       * Chamado automaticamente pelo onRehydrateStorage abaixo
       */
      setHydrated: (state) =>
        set({ isHydrated: state }),
    }),
    {
      name: 'auth-storage', // Chave no localStorage
      storage: createJSONStorage(() => localStorage),

      /**
       * CRÍTICO: Este callback é chamado QUANDO o Zustand termina de ler o localStorage
       * 
       * FLUXO:
       * 1. Página carrega → user=null, token=null, isHydrated=false
       * 2. Zustand lê localStorage (assíncrono)
       * 3. Se encontrou dados: user e token são preenchidos
       * 4. onRehydrateStorage é chamado → setamos isHydrated=true
       * 5. Agora o layout.tsx PODE verificar com segurança se está logado
       */
      onRehydrateStorage: () => {
        return (state, error) => {
          if (error) {
            console.error('Erro ao hidratar authStore:', error);
          }
          // Marca que a hidratação terminou (com ou sucesso ou erro)
          state?.setHydrated(true);
        };
      },
    }
  )
);
```

