import { Injectable } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CreatePricingDto } from './dto/create-pricing.dto';

@Injectable()
export class PricingService {
  constructor(private prisma: PrismaService) {}

  async findAll(userId: string) {
    return this.prisma.pricing.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
    });
  }

  async create(userId: string, dto: CreatePricingDto) {
    return this.prisma.pricing.create({
      data: {
        userId,
        ...dto,
        softwareCost: dto.softwareCost || 0,
        profitMargin: dto.profitMargin || 20,
        status: dto.status || 'RASCUNHO',
      },
    });
  }

  async update(userId: string, pricingId: string, dto: CreatePricingDto) {
    return this.prisma.pricing.update({
      where: { id: pricingId, userId },
      data: {
        ...dto,
        softwareCost: dto.softwareCost || 0,
        profitMargin: dto.profitMargin || 20,
      },
    });
  }

  async remove(userId: string, pricingId: string) {
    return this.prisma.pricing.delete({
      where: { id: pricingId, userId },
    });
  }

  /**
   * Calcula métricas da precificação
   */
  async getMetrics(userId: string) {
    const totalPricings = await this.prisma.pricing.count({
      where: { userId },
    });

    const avgValue = await this.prisma.pricing.aggregate({
      where: { userId },
      _avg: { finalValue: true },
    });

    return {
      totalPricings,
      averageFinalValue: parseFloat((avgValue._avg.finalValue || 0).toFixed(2)),
    };
  }
}
```

####  **ARQUIVO 3: `backend/src/pricing/pricing.controller.ts`**

```typescript
import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  UseGuards,
  Request,
} from '@nestjs/common';
import { PricingService } from './pricing.service';
import { CreatePricingDto } from './dto/create-pricing.dto';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';

@Controller('pricings')
@UseGuards(JwtAuthGuard)
export class PricingController {
  constructor(private pricingService: PricingService) {}

  @Get()
  async findAll(@Request() req) {
    const pricings = await this.pricingService.findAll(req.user.id);
    return { data: pricings };
  }

  @Get('metrics')
  async getMetrics(@Request() req) {
    const metrics = await this.pricingService.getMetrics(req.user.id);
    return { data: metrics };
  }

  @Post()
  async create(@Request() req, @Body() dto: CreatePricingDto) {
    const pricing = await this.pricingService.create(req.user.id, dto);
    return { message: 'Precificação criada com sucesso!', data: pricing };
  }

  @Put(':id')
  async update(
    @Request() req,
    @Param('id') id: string,
    @Body() dto: CreatePricingDto,
  ) {
    const pricing = await this.pricingService.update(req.user.id, id, dto);
    return { message: 'Precificação atualizada!', data: pricing };
  }

  @Delete(':id')
  async remove(@Request() req, @Param('id') id: string) {
    await this.pricingService.remove(req.user.id, id);
    return { message: 'Precificação removida!' };
  }
}
