  CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';

interface ClientMetrics { totalActive: number; monthlyRevenue: number; averageTicket: number; newClientsThisMonth: number; }
interface EmployeeMetrics { totalActive: number; admissionsThisMonth: number; dismissalsThisMonth: number; turnoverRate: number; }
interface PricingMetrics { totalPricings: number; averageFinalValue: number; }
interface PlanningMetrics { totalPlans: number; completedPlans: number; averageProgress: number; }
interface Client { id: string; companyName: string; serviceType: string; status: string; }

export default function DashboardPage() {
  const { user } = useAuthStore();
  const [clientMetrics, setClientMetrics] = useState<ClientMetrics | null>(null);
  const [employeeMetrics, setEmployeeMetrics] = useState<EmployeeMetrics | null>(null);
  const [pricingMetrics, setPricingMetrics] = useState<PricingMetrics | null>(null);
  const [planningMetrics, setPlanningMetrics] = useState<PlanningMetrics | null>(null);
  const [clients, setClients] = useState<Client[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [cliRes, empRes, priRes, plaRes, clientsRes] = await Promise.all([
        api.get('/clients/metrics'),
        api.get('/employees/metrics'),
        api.get('/pricings/metrics'),
        api.get('/plannings/metrics'),
        api.get('/clients'),
      ]);
      setClientMetrics(cliRes.data.data || null);
      setEmployeeMetrics(empRes.data.data || null);
      setPricingMetrics(priRes.data.data || null);
      setPlanningMetrics(plaRes.data.data || null);
      setClients(clientsRes.data.data || []);
    } catch (err: any) {
      console.error('Erro ao carregar dashboard:', err);
      if (err.response?.status !== 401) setError('Erro ao carregar dados.');
    } finally {
      setLoading(false);
    }
  }

  const clientServiceData = (() => {
    const count: Record<string, number> = {};
    clients.forEach((c) => {
      if (c.status === 'ATIVO') count[c.serviceType] = (count[c.serviceType] || 0) + 1;
    });
    return Object.entries(count).map(([name, value]) => ({ name, value }));
  })();

  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6'];
  const workforceData = [{ name: 'Este Mês', Admissões: employeeMetrics?.admissionsThisMonth || 0, Demissões: employeeMetrics?.dismissalsThisMonth || 0 }];

  if (loading) return <div className="flex items-center justify-center h-96"><Loader2 className="h-12 w-12 text-blue-600 animate-spin" /></div>;
  if (error) return <div className="flex items-center justify-center h-96"><AlertCircle className="h-12 w-12 text-red-500" /><p className="ml-2">{error}</p></div>;

  return (
    <div className="max-w-7xl mx-auto space-y-8">
      <div>
        <h1 className="text-3xl font-bold text-slate-900">Visão Geral</h1>
        <p className="text-slate-600">Resumo executivo do seu escritório.</p>
      </div>

      {/* KPIs */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <KpiCard icon={Briefcase} label="Clientes Ativos" value={clientMetrics?.totalActive || 0} trend={`${clientMetrics?.newClientsThisMonth || 0} novos`} color="blue" />
        <KpiCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${(clientMetrics?.monthlyRevenue || 0).toFixed(2)}`} trend={`Ticket: R$ ${(clientMetrics?.averageTicket || 0).toFixed(2)}`} color="green" />
        <KpiCard icon={Users} label="Colaboradores" value={employeeMetrics?.totalActive || 0} trend={`Turnover: ${employeeMetrics?.turnoverRate || 0}%`} color="purple" />
        <KpiCard icon={Target} label="Metas" value={planningMetrics?.totalPlans || 0} trend={`${planningMetrics?.completedPlans || 0} concluídas`} color="orange" />
      </div>

      {/* Gráficos */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Carteira por Tipo de Serviço</h3>
          {clientServiceData.length > 0 ? (
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie data={clientServiceData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={3} dataKey="value">
                  {clientServiceData.map((_, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          ) : <p className="text-center text-slate-500 py-12">Nenhum cliente ativo para exibir.</p>}
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-bold text-slate-900 mb-4">Movimentação de Pessoal</h3>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={workforceData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="Admissões" fill="#10b981" radius={[8, 8, 0, 0]} />
              <Bar dataKey="Demissões" fill="#ef4444" radius={[8, 8, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
