```typescript
'use client';

/**
 * =================================================================
 * MÓDULO DE GESTÃO DE PESSOAS (COLABORADORES)
 * =================================================================
 * 
 * Este arquivo gerencia o CRUD (Criar, Ler, Atualizar, Deletar) 
 * e a exportação de dados dos colaboradores do escritório.
 * 
 * CARACTERÍSTICAS PROFISSIONAIS:
 * - Integração com Zustand para autenticação.
 * - Cálculo automático de Turnover (Rotatividade) no backend.
 * - Exportação CSV com suporte nativo a UTF-8 (acentos corretos no Excel).
 * - Filtragem em tempo real e métricas de admissão/demissão.
 */

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import { exportToCSV } from '@/lib/exportToCSV'; // <-- NOSSO UTILITÁRIO DE EXPORTAÇÃO
import {
  Users,
  UserPlus,
  TrendingUp,
  UserMinus,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
  Download, // <-- Ícone para o botão de exportar
} from 'lucide-react';

// --- TIPOS (TypeScript) ---
interface Employee {
  id: string;
  name: string;
  email: string;
  phone: string;
  position: string;
  department: string;
  admissionDate: string;
  dismissalDate: string | null;
  salary: number;
  status: string;
}

interface Metrics {
  totalActive: number;
  totalEmployees: number;
  admissionsThisMonth: number;
  dismissalsThisMonth: number;
  turnoverRate: number;
}

export default function PessoasPage() {
  const { user } = useAuthStore();

  // --- ESTADOS DE DADOS ---
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // --- ESTADOS DE UI E FORMULÁRIO ---
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [form, setForm] = useState({
    name: '', email: '', phone: '', position: '', department: '',
    admissionDate: '', dismissalDate: '', salary: '', status: 'ACTIVE',
  });

  // 1. CARREGAR DADOS INICIAIS
  useEffect(() => { loadData(); }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [empRes, metRes] = await Promise.all([
        api.get('/employees'),
        api.get('/employees/metrics'),
      ]);
      setEmployees(empRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      if (err.response?.status !== 401) setError('Erro ao carregar dados.');
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAGEM INTELIGENTE (Busca em tempo real)
  const filteredEmployees = employees.filter((emp) =>
    emp.name.toLowerCase().includes(search.toLowerCase()) ||
    emp.position.toLowerCase().includes(search.toLowerCase()) ||
    emp.department.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO (Modo Criar ou Editar)
  function openForm(employee?: Employee) {
    if (employee) {
      setEditingId(employee.id);
      setForm({
        name: employee.name, email: employee.email || '', phone: employee.phone || '',
        position: employee.position, department: employee.department || '',
        admissionDate: employee.admissionDate.split('T')[0],
        dismissalDate: employee.dismissalDate?.split('T')[0] || '',
        salary: employee.salary?.toString() || '', status: employee.status,
      });
    } else {
      setEditingId(null);
      setForm({
        name: '', email: '', phone: '', position: '', department: '',
        admissionDate: '', dismissalDate: '', salary: '', status: 'ACTIVE',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR (POST ou PUT)
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      const payload = {
        ...form,
        salary: form.salary ? parseFloat(form.salary) : null,
        admissionDate: form.admissionDate,
        dismissalDate: form.dismissalDate || null,
      };
      if (editingId) await api.put(`/employees/${editingId}`, payload);
      else await api.post('/employees', payload);

      setShowForm(false);
      await loadData();
    } catch (err) {
      alert('Erro ao salvar colaborador. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER (DELETE)
  async function handleDelete(id: string) {
    if (!confirm('Tem certeza que deseja remover este colaborador?')) return;
    try {
      await api.delete(`/employees/${id}`);
      await loadData();
    } catch (err) {
      alert('Erro ao remover colaborador.');
    }
  }

  // 6. EXPORTAR PARA CSV (Lógica Inteligente)
  function handleExport() {
    // Se o usuário estiver buscando algo, exporta apenas o filtro.
    // Caso contrário, exporta a lista completa de colaboradores.
    const dataToExport = search.trim() !== '' ? filteredEmployees : employees;

    // Chama nossa função utilitária que já trata acentos e formatação
    exportToCSV(dataToExport, 'colaboradores_radar_clone');
  }

  // --- RENDERIZAÇÃO: TELA DE CARREGAMENTO ---
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA DE ERRO ---
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA PRINCIPAL ---
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho com Ações */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Gestão de Pessoas</h1>
          <p className="text-slate-600">Gerencie sua equipe e monitore o turnover</p>
        </div>
        <div className="flex gap-3">
          {/* Botão de Exportação */}
          <button
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Download className="h-5 w-5" />
            Exportar CSV
          </button>
          {/* Botão de Novo Colaborador */}
          <button
            onClick={() => openForm()}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Plus className="h-5 w-5" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
          <MetricCard icon={Users} label="Total Ativos" value={metrics.totalActive} color="blue" />
          <MetricCard icon={UserPlus} label="Admissões (mês)" value={metrics.admissionsThisMonth} color="green" />
          <MetricCard icon={UserMinus} label="Demissões (mês)" value={metrics.dismissalsThisMonth} color="red" />
          <MetricCard icon={TrendingUp} label="Turnover" value={`${metrics.turnoverRate}%`} color="orange" />
