```typescript
'use client';

/**
 * =================================================================
 * MÓDULO DE GESTÃO DE CLIENTES (VERSÃO FINAL COM TOASTS)
 * =================================================================
 * 
 * Este arquivo gerencia o CRUD (Criar, Ler, Atualizar, Deletar) 
 * e a exportação de dados da carteira de clientes do escritório.
 * 
 * CARACTERÍSTICAS PROFISSIONAIS:
 * - Integração com Zustand para autenticação.
 * - Axios com interceptors para segurança.
 * - Exportação CSV com suporte nativo a UTF-8 (acentos corretos no Excel).
 * - Notificações Toast elegantes (sonner) substituindo alert() e confirm().
 * - Filtragem em tempo real e métricas de faturamento.
 */

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import { exportToCSV } from '@/lib/exportToCSV';
import { toast } from 'sonner'; // <-- NOSSO SISTEMA DE NOTIFICAÇÕES
import {
  Briefcase,
  UserPlus,
  TrendingUp,
  DollarSign,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
  Download,
} from 'lucide-react';

// --- TIPOS (TypeScript) ---
interface Client {
  id: string;
  companyName: string;
  cnpj: string;
  serviceType: string;
  monthlyFee: number;
  status: string;
  startDate: string;
  endDate: string | null;
  contactName: string;
  contactEmail: string;
  contactPhone: string;
  observations: string;
}

interface Metrics {
  totalActive: number;
  totalClients: number;
  monthlyRevenue: number;
  newClientsThisMonth: number;
  averageTicket: number;
}

export default function ClientesPage() {
  const { user } = useAuthStore();

  // --- ESTADOS DE DADOS ---
  const [clients, setClients] = useState<Client[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // --- ESTADOS DE UI E FORMULÁRIO ---
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [form, setForm] = useState({
    companyName: '', cnpj: '', serviceType: 'CONTABIL', monthlyFee: '',
    status: 'ATIVO', startDate: '', endDate: '', contactName: '',
    contactEmail: '', contactPhone: '', observations: '',
  });

  // 1. CARREGAR DADOS INICIAIS
  useEffect(() => { loadData(); }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [cliRes, metRes] = await Promise.all([
        api.get('/clients'),
        api.get('/clients/metrics'),
      ]);
      setClients(cliRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados.');
        toast.error('Falha ao carregar dados dos clientes');
      }
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAGEM INTELIGENTE (Busca em tempo real)
  const filteredClients = clients.filter((cli) =>
    cli.companyName.toLowerCase().includes(search.toLowerCase()) ||
    cli.contactName?.toLowerCase().includes(search.toLowerCase()) ||
    cli.serviceType.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO (Modo Criar ou Editar)
  function openForm(client?: Client) {
    if (client) {
      setEditingId(client.id);
      setForm({
        companyName: client.companyName, cnpj: client.cnpj || '',
        serviceType: client.serviceType, monthlyFee: client.monthlyFee.toString(),
        status: client.status, startDate: client.startDate.split('T')[0],
        endDate: client.endDate?.split('T')[0] || '', contactName: client.contactName || '',
        contactEmail: client.contactEmail || '', contactPhone: client.contactPhone || '',
        observations: client.observations || '',
      });
    } else {
      setEditingId(null);
      setForm({
        companyName: '', cnpj: '', serviceType: 'CONTABIL', monthlyFee: '',
        status: 'ATIVO', startDate: '', endDate: '', contactName: '',
        contactEmail: '', contactPhone: '', observations: '',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR (POST ou PUT) COM TOASTS
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      const payload = {
        ...form,
        monthlyFee: parseFloat(form.monthlyFee) || 0,
        startDate: form.startDate,
        endDate: form.endDate || undefined,
      };

      if (editingId) {
        await api.put(`/clients/${editingId}`, payload);
        toast.success('Cliente atualizado com sucesso!');
      } else {
        await api.post('/clients', payload);
        toast.success('Cliente criado com sucesso!');
      }

      setShowForm(false);
      await loadData();
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      toast.error('Erro ao salvar cliente. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER (DELETE) COM TOAST INTERATIVO
  // Substitui o confirm() nativo por um toast elegante com botões
  function handleDelete(id: string) {
    toast('Tem certeza que deseja remover este cliente?', {
      description: 'Esta ação não pode ser desfeita.',
      action: {
        label: 'Remover',
        onClick: async () => {
          try {
            await api.delete(`/clients/${id}`);
            toast.success('Cliente removido com sucesso!');
            await loadData();
          } catch (err) {
            toast.error('Erro ao remover cliente.');
          }
        },
      },
      cancel: {
        label: 'Cancelar',
      },
      style: {
        background: '#ffffff',
        color: '#0f172a',
        border: '1px solid #e2e8f0',
      },
    });
  }

  // 6. EXPORTAR PARA CSV (Lógica Inteligente)
  function handleExport() {
    const dataToExport = search.trim() !== '' ? filteredClients : clients;

    if (dataToExport.length === 0) {
      toast.warning('Nenhum dado disponível para exportar');
      return;
    }

    exportToCSV(dataToExport, 'carteira_de_clientes');
    toast.success(`${dataToExport.length} cliente(s) exportado(s) com sucesso!`);
  }

  // --- RENDERIZAÇÃO: TELA DE CARREGAMENTO ---
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA DE ERRO ---
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA PRINCIPAL ---
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho com Ações */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Gestão de Clientes</h1>
          <p className="text-slate-600">Acompanhe sua carteira de clientes e faturamento</p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Download className="h-5 w-5" />
            Exportar CSV
          </button>
          <button
            onClick={() => openForm()}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Plus className="h-5 w-5" />
            Novo Cliente
          </button>
        </div>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 mb-8">
          <MetricCard icon={Briefcase} label="Total Ativos" value={metrics.totalActive} color="blue" />
          <MetricCard icon={DollarSign} label="Faturamento Mensal" value={`R$ ${metrics.monthlyRevenue.toFixed(2)}`} color="green" />
          <MetricCard icon={UserPlus} label="Novos (mês)" value={metrics.newClientsThisMonth} color="purple" />
          <MetricCard icon={TrendingUp} label="Ticket Médio" value={`R$ ${metrics.averageTicket.toFixed(2)}`} color="orange" />
          <MetricCard icon={Briefcase} label="Total Geral" value={metrics.totalClients} color="slate" />
        </div>
      )}

      {/* Barra de Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por empresa, contato ou tipo de serviço..."
            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Tabela de Clientes */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredClients.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <Briefcase className="h-12 w-12 mx-auto mb-4 text-slate-300" />
            <p className="text-lg font-medium">Nenhum cliente encontrado</p>
            <p className="text-sm mt-1">Clique em "Novo Cliente" para começar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Empresa</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Serviço</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Honorário</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Status</th>
                  <th className="text-right px-6 py-3 text-xs font-medium text-slate-500 uppercase">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {filteredClients.map((cli) => (
                  <tr key={cli.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-900">{cli.companyName}</div>
                      {cli.contactName && <div className="text-sm text-slate-500">{cli.contactName}</div>}
                    </td>
                    <td className="px-6 py-4 text-slate-700">{cli.serviceType}</td>
                    <td className="px-6 py-4 text-slate-700">R$ {cli.monthlyFee.toFixed(2)}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        cli.status === 'ATIVO' ? 'bg-green-100 text-green-800' : 
                        cli.status === 'PROSPECT' ? 'bg-yellow-100 text-yellow-800' : 'bg-red-100 text-red-800'
                      }`}>
                        {cli.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button onClick={() => openForm(cli)} className="text-blue-600 hover:text-blue-800 mr-3" title="Editar">
                        <Edit2 className="h-4 w-4" />
                      </button>
                      <button onClick={() => handleDelete(cli.id)} className="text-red-600 hover:text-red-800" title="Remover">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* MODAL DE FORMULÁRIO */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-6 border-b border-slate-200 sticky top-0 bg-white z-10">
              <h2 className="text-xl font-bold text-slate-900">
                {editingId ? 'Editar Cliente' : 'Novo Cliente'}
              </h2>
              <button onClick={() => setShowForm(false)} className="text-slate-400 hover:text-slate-600">
                <X className="h-6 w-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-1">Razão Social *</label>
                  <input type="text" required value={form.companyName} onChange={(e) => setForm({ ...form, companyName: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">CNPJ</label>
                  <input type="text" value={form.cnpj} onChange={(e) => setForm({ ...form, cnpj: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Tipo de Serviço *</label>
                  <select required value={form.serviceType} onChange={(e) => setForm({ ...form, serviceType: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500">
                    <option value="CONTABIL">Contábil</option>
                    <option value="FISCAL">Fiscal</option>
                    <option value="PESSOAL">Pessoal</option>
                    <option value="COMPLETO">Completo</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Honorário Mensal (R$) *</label>
                  <input type="number" step="0.01" required value={form.monthlyFee} onChange={(e) => setForm({ ...form, monthlyFee: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Status *</label>
                  <select required value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500">
                    <option value="ATIVO">Ativo</option>
                    <option value="PROSPECT">Prospect</option>
                    <option value="INATIVO">Inativo</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Data de Início *</label>
                  <input type="date" required value={form.startDate} onChange={(e) => setForm({ ...form, startDate: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Data de Encerramento</label>
                  <input type="date" value={form.endDate} onChange={(e) => setForm({ ...form, endDate: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Nome do Contato</label>
                  <input type="text" value={form.contactName} onChange={(e) => setForm({ ...form, contactName: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">E-mail do Contato</label>
                  <input type="email" value={form.contactEmail} onChange={(e) => setForm({ ...form, contactEmail: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-1">Observações</label>
                  <textarea value={form.observations} onChange={(e) => setForm({ ...form, observations: e.target.value })} rows={3} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t border-slate-200 sticky bottom-0 bg-white">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg transition-colors">
                  Cancelar
                </button>
                <button type="submit" disabled={submitting} className="flex items-center gap-2 px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors disabled:opacity-50">
                  {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
                  {submitting ? 'Salvando...' : 'Salvar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

// --- COMPONENTE AUXILIAR: Card de Métrica ---
function MetricCard({ icon: Icon, label, value, color }: { icon: any; label: string; value: string | number; color: string }) {
  const colorClasses: Record<string, string> = {
    blue: 'bg-blue-100 text-blue-600', green: 'bg-green-100 text-green-600',
    purple: 'bg-purple-100 text-purple-600', orange: 'bg-orange-100 text-orange-600',
    slate: 'bg-slate-100 text-slate-600',
  };
  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
      <div className="flex items-center gap-3 mb-3">
        <div className={`p-2 rounded-lg ${colorClasses[color]}`}>
          <Icon className="h-5 w-5" />
        </div>
        <span className="text-sm font-medium text-slate-600">{label}</span>
      </div>
      <div className="text-3xl font-bold text-slate-900">{value}</div>
    </div>
  );
}
```

