'use client';

import { useAuthStore } from '@/store/authStore';
import { useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { LayoutDashboard, Users, Briefcase, Calculator, Target, LogOut, Building2, Loader2 } from 'lucide-react';

