'use client';

/**
 * =================================================================
 * MÓDULO DE GESTÃO DE PESSOAS (VERSÃO FINAL COM TOASTS)
 * =================================================================
 * 
 * Este arquivo gerencia o CRUD (Criar, Ler, Atualizar, Deletar) 
 * e a exportação de dados dos colaboradores do escritório.
 * 
 * CARACTERÍSTICAS PROFISSIONAIS:
 * - Integração com Zustand para autenticação.
 * - Cálculo automático de Turnover (Rotatividade) no backend.
 * - Exportação CSV com suporte nativo a UTF-8 (acentos corretos no Excel).
 * - Notificações Toast elegantes (sonner) substituindo alert() e confirm().
 * - Filtragem em tempo real e métricas de admissão/demissão.
 */

import { useState, useEffect } from 'react';
import { useAuthStore } from '@/store/authStore';
import api from '@/lib/axios';
import { exportToCSV } from '@/lib/exportToCSV';
import { toast } from 'sonner'; // <-- NOSSO SISTEMA DE NOTIFICAÇÕES
import {
  Users,
  UserPlus,
  TrendingUp,
  UserMinus,
  Plus,
  Search,
  Edit2,
  Trash2,
  X,
  Loader2,
  AlertCircle,
  Download,
} from 'lucide-react';

// --- TIPOS (TypeScript) ---
interface Employee {
  id: string;
  name: string;
  email: string;
  phone: string;
  position: string;
  department: string;
  admissionDate: string;
  dismissalDate: string | null;
  salary: number;
  status: string;
}

interface Metrics {
  totalActive: number;
  totalEmployees: number;
  admissionsThisMonth: number;
  dismissalsThisMonth: number;
  turnoverRate: number;
}

export default function PessoasPage() {
  const { user } = useAuthStore();

  // --- ESTADOS DE DADOS ---
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [metrics, setMetrics] = useState<Metrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // --- ESTADOS DE UI E FORMULÁRIO ---
  const [search, setSearch] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const [form, setForm] = useState({
    name: '', email: '', phone: '', position: '', department: '',
    admissionDate: '', dismissalDate: '', salary: '', status: 'ACTIVE',
  });

  // 1. CARREGAR DADOS INICIAIS
  useEffect(() => { loadData(); }, []);

  async function loadData() {
    try {
      setLoading(true);
      setError(null);
      const [empRes, metRes] = await Promise.all([
        api.get('/employees'),
        api.get('/employees/metrics'),
      ]);
      setEmployees(empRes.data.data || []);
      setMetrics(metRes.data.data || null);
    } catch (err: any) {
      if (err.response?.status !== 401) {
        setError('Erro ao carregar dados.');
        toast.error('Falha ao carregar dados dos colaboradores');
      }
    } finally {
      setLoading(false);
    }
  }

  // 2. FILTRAGEM INTELIGENTE (Busca em tempo real)
  const filteredEmployees = employees.filter((emp) =>
    emp.name.toLowerCase().includes(search.toLowerCase()) ||
    emp.position.toLowerCase().includes(search.toLowerCase()) ||
    emp.department.toLowerCase().includes(search.toLowerCase())
  );

  // 3. ABRIR FORMULÁRIO (Modo Criar ou Editar)
  function openForm(employee?: Employee) {
    if (employee) {
      setEditingId(employee.id);
      setForm({
        name: employee.name, email: employee.email || '', phone: employee.phone || '',
        position: employee.position, department: employee.department || '',
        admissionDate: employee.admissionDate.split('T')[0],
        dismissalDate: employee.dismissalDate?.split('T')[0] || '',
        salary: employee.salary?.toString() || '', status: employee.status,
      });
    } else {
      setEditingId(null);
      setForm({
        name: '', email: '', phone: '', position: '', department: '',
        admissionDate: '', dismissalDate: '', salary: '', status: 'ACTIVE',
      });
    }
    setShowForm(true);
  }

  // 4. SALVAR (POST ou PUT) COM TOASTS
  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    try {
      const payload = {
        ...form,
        salary: form.salary ? parseFloat(form.salary) : null,
        admissionDate: form.admissionDate,
        dismissalDate: form.dismissalDate || null,
      };

      if (editingId) {
        await api.put(`/employees/${editingId}`, payload);
        toast.success('Colaborador atualizado com sucesso!');
      } else {
        await api.post('/employees', payload);
        toast.success('Colaborador criado com sucesso!');
      }

      setShowForm(false);
      await loadData();
    } catch (err: any) {
      console.error('Erro ao salvar:', err);
      toast.error('Erro ao salvar colaborador. Verifique os dados.');
    } finally {
      setSubmitting(false);
    }
  }

  // 5. REMOVER (DELETE) COM TOAST INTERATIVO
  // Substitui o confirm() nativo por um toast elegante com botões
  function handleDelete(id: string) {
    toast('Tem certeza que deseja remover este colaborador?', {
      description: 'Esta ação não pode ser desfeita.',
      action: {
        label: 'Remover',
        onClick: async () => {
          try {
            await api.delete(`/employees/${id}`);
            toast.success('Colaborador removido com sucesso!');
            await loadData();
          } catch (err) {
            toast.error('Erro ao remover colaborador.');
          }
        },
      },
      cancel: {
        label: 'Cancelar',
      },
      style: {
        background: '#ffffff',
        color: '#0f172a',
        border: '1px solid #e2e8f0',
      },
    });
  }

  // 6. EXPORTAR PARA CSV (Lógica Inteligente)
  function handleExport() {
    const dataToExport = search.trim() !== '' ? filteredEmployees : employees;

    if (dataToExport.length === 0) {
      toast.warning('Nenhum dado disponível para exportar');
      return;
    }

    exportToCSV(dataToExport, 'colaboradores_radar_clone');
    toast.success(`${dataToExport.length} colaborador(es) exportado(s) com sucesso!`);
  }

  // --- RENDERIZAÇÃO: TELA DE CARREGAMENTO ---
  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 text-blue-600 animate-spin" />
        <span className="ml-2 text-slate-600">Carregando dados...</span>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA DE ERRO ---
  if (error) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="text-center">
          <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
          <p className="text-slate-700 mb-4">{error}</p>
          <button onClick={loadData} className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700">
            Tentar novamente
          </button>
        </div>
      </div>
    );
  }

  // --- RENDERIZAÇÃO: TELA PRINCIPAL ---
  return (
    <div className="max-w-7xl">
      {/* Cabeçalho com Ações */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 mb-2">Gestão de Pessoas</h1>
          <p className="text-slate-600">Gerencie sua equipe e monitore o turnover</p>
        </div>
        <div className="flex gap-3">
          {/* Botão de Exportação */}
          <button
            onClick={handleExport}
            className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Download className="h-5 w-5" />
            Exportar CSV
          </button>
          {/* Botão de Novo Colaborador */}
          <button
            onClick={() => openForm()}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors shadow-sm"
          >
            <Plus className="h-5 w-5" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Cards de Métricas */}
      {metrics && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
          <MetricCard icon={Users} label="Total Ativos" value={metrics.totalActive} color="blue" />
          <MetricCard icon={UserPlus} label="Admissões (mês)" value={metrics.admissionsThisMonth} color="green" />
          <MetricCard icon={UserMinus} label="Demissões (mês)" value={metrics.dismissalsThisMonth} color="red" />
          <MetricCard icon={TrendingUp} label="Turnover" value={`${metrics.turnoverRate}%`} color="orange" />
        </div>
      )}

      {/* Barra de Busca */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 mb-4">
        <div className="relative">
          <Search className="absolute left-3 top-3 h-5 w-5 text-slate-400" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Buscar por nome, cargo ou departamento..."
            className="w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* Tabela de Colaboradores */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        {filteredEmployees.length === 0 ? (
          <div className="p-12 text-center text-slate-500">
            <Users className="h-12 w-12 mx-auto mb-4 text-slate-300" />
            <p className="text-lg font-medium">Nenhum colaborador encontrado</p>
            <p className="text-sm mt-1">Clique em "Novo Colaborador" para começar</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-slate-50 border-b border-slate-200">
                <tr>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Nome</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Cargo</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Admissão</th>
                  <th className="text-left px-6 py-3 text-xs font-medium text-slate-500 uppercase">Status</th>
                  <th className="text-right px-6 py-3 text-xs font-medium text-slate-500 uppercase">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200">
                {filteredEmployees.map((emp) => (
                  <tr key={emp.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-900">{emp.name}</div>
                      {emp.department && <div className="text-sm text-slate-500">{emp.department}</div>}
                    </td>
                    <td className="px-6 py-4 text-slate-700">{emp.position}</td>
                    <td className="px-6 py-4 text-slate-700">
                      {new Date(emp.admissionDate).toLocaleDateString('pt-BR')}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        emp.status === 'ACTIVE' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                      }`}>
                        {emp.status === 'ACTIVE' ? 'Ativo' : 'Desligado'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button onClick={() => openForm(emp)} className="text-blue-600 hover:text-blue-800 mr-3" title="Editar">
                        <Edit2 className="h-4 w-4" />
                      </button>
                      <button onClick={() => handleDelete(emp.id)} className="text-red-600 hover:text-red-800" title="Remover">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* MODAL DE FORMULÁRIO */}
      {showForm && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between p-6 border-b border-slate-200 sticky top-0 bg-white z-10">
              <h2 className="text-xl font-bold text-slate-900">
                {editingId ? 'Editar Colaborador' : 'Novo Colaborador'}
              </h2>
              <button onClick={() => setShowForm(false)} className="text-slate-400 hover:text-slate-600">
                <X className="h-6 w-6" />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-1">Nome Completo *</label>
                  <input type="text" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">E-mail</label>
                  <input type="email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Telefone</label>
                  <input type="text" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Cargo *</label>
                  <input type="text" required value={form.position} onChange={(e) => setForm({ ...form, position: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Departamento</label>
                  <input type="text" value={form.department} onChange={(e) => setForm({ ...form, department: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Data de Admissão *</label>
                  <input type="date" required value={form.admissionDate} onChange={(e) => setForm({ ...form, admissionDate: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Data de Desligamento</label>
                  <input type="date" value={form.dismissalDate} onChange={(e) => setForm({ ...form, dismissalDate: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Salário (R$)</label>
                  <input type="number" step="0.01" value={form.salary} onChange={(e) => setForm({ ...form, salary: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Status *</label>
                  <select required value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500">
                    <option value="ACTIVE">Ativo</option>
                    <option value="INACTIVE">Desligado</option>
                  </select>
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t border-slate-200 sticky bottom-0 bg-white">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg transition-colors">
                  Cancelar
                </button>
                <button type="submit" disabled={submitting} className="flex items-center gap-2 px-6 py-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-lg transition-colors disabled:opacity-50">
                  {submitting && <Loader2 className="h-4 w-4 animate-spin" />}
                  {submitting ? 'Salvando...' : 'Salvar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

// --- COMPONENTE AUXILIAR: Card de Métrica ---
function MetricCard({ icon: Icon, label, value, color }: { icon: any; label: string; value: string | number; color: string }) {
  const colorClasses: Record<string, string> = {
    blue: 'bg-blue-100 text-blue-600', green: 'bg-green-100 text-green-600',
    red: 'bg-red-100 text-red-600', orange: 'bg-orange-100 text-orange-600',
  };
  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
      <div className="flex items-center gap-3 mb-3">
        <div className={`p-2 rounded-lg ${colorClasses[color]}`}>
          <Icon className="h-5 w-5" />
        </div>
        <span className="text-sm font-medium text-slate-600">{label}</span>
      </div>
      <div className="text-3xl font-bold text-slate-900">{value}</div>
    </div>
  );
}
